package com.drogaria.backend.controller;
import com.drogaria.backend.dto.*; import com.drogaria.backend.service.FuncionarioService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/funcionario") public class FuncionarioController { private final FuncionarioService s; public FuncionarioController(FuncionarioService s){this.s=s;} @GetMapping public List<FuncionarioResponse> listar(){return s.listar();} @GetMapping("/{id}") public FuncionarioResponse buscar(@PathVariable Integer id){return s.buscar(id);} @PostMapping public ResponseEntity<FuncionarioResponse> salvar(@Valid @RequestBody FuncionarioRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(s.salvar(r));} @PutMapping("/{id}") public FuncionarioResponse atualizar(@PathVariable Integer id,@Valid @RequestBody FuncionarioRequest r){return s.atualizar(id,r);} @DeleteMapping("/{id}") public ResponseEntity<Void> excluir(@PathVariable Integer id){s.excluir(id);return ResponseEntity.noContent().build();} }